"""The API knowledge packs behind LX101.

Two files ship with lintex, both loaded once per process:

* ``curated.toml``  hand-written entries with specific, tested fixes.
* ``typeshed.json`` generated by ``python -m lintex.knowledge.sync`` from
  typeshed's ``stdlib/VERSIONS`` (module removals) and ``@deprecated``
  stub decorators. Never edit it by hand; regenerate it.

Curated entries win when both describe the same name. Nothing here touches
the network: syncing is a maintainer step, and the generated file is data
shipped in the wheel.
"""

from __future__ import annotations

import json
import re
import sys
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from lintex.models import Severity

if sys.version_info >= (3, 11):
    import tomllib
else:  # pragma: no cover
    import tomli as tomllib

_HERE = Path(__file__).parent
CURATED_PATH = _HERE / "curated.toml"
TYPESHED_PATH = _HERE / "typeshed.json"

STATUSES = ("removed", "deprecated", "py2")
PYTHON = "python"


def parse_version(text: str) -> tuple[int, ...]:
    return tuple(int(p) for p in re.findall(r"\d+", str(text))[:3])


@dataclass(frozen=True)
class ApiEntry:
    name: str
    status: str
    version: str = ""
    package: str = PYTHON
    fix: str = ""
    message: str = ""
    source: str = "curated"

    @property
    def is_python(self) -> bool:
        return self.package == PYTHON

    def describe(self, target: tuple[int, int] | None) -> str:
        """The predicate after the name: '`x` <describe>.'"""
        if self.message:
            return self.message
        if self.status == "py2":
            return "is Python 2 only and does not exist in Python 3"
        where = f"Python {self.version}" if self.is_python else f"{self.package} {self.version}"
        if self.status == "deprecated":
            return (
                f"is deprecated ({where})" if self.version else f"is deprecated in {self.package}"
            )
        if self.is_python and target is not None and target < parse_version(self.version):
            return (
                f"was removed in Python {self.version}. This project's minimum is "
                f"Python {target[0]}.{target[1]}, where it still exists, but it breaks on "
                f"{self.version}+"
            )
        return f"was removed in {where}"

    def severity(self, target: tuple[int, int] | None) -> Severity:
        if self.status == "deprecated":
            return Severity.WARNING
        if self.status == "removed" and self.is_python and target is not None:
            return Severity.ERROR if target >= parse_version(self.version) else Severity.WARNING
        return Severity.ERROR


class Knowledge:
    def __init__(self, apis: dict[str, ApiEntry], methods: dict[str, ApiEntry], sources: dict):
        self.apis = apis
        self.methods = methods
        self.sources = sources

    def match_prefix(self, qualified: str) -> tuple[str, ApiEntry] | None:
        """The longest dotted prefix of ``qualified`` that is a known-bad API."""
        parts = qualified.split(".")
        for i in range(len(parts), 0, -1):
            key = ".".join(parts[:i])
            entry = self.apis.get(key)
            if entry is not None:
                return key, entry
        return None

    def counts(self) -> dict[str, int]:
        out: dict[str, int] = {}
        for entry in (*self.apis.values(), *self.methods.values()):
            out[entry.status] = out.get(entry.status, 0) + 1
        return out


def _entry(raw: dict, source: str) -> ApiEntry:
    status = raw.get("status", "removed")
    if status not in STATUSES:
        raise ValueError(f"knowledge entry {raw.get('name')!r}: bad status {status!r}")
    if not raw.get("name") or not raw.get("fix"):
        raise ValueError(f"knowledge entry {raw!r} needs a name and a fix")
    return ApiEntry(
        name=raw["name"],
        status=status,
        version=str(raw.get("version", "")),
        package=raw.get("package", PYTHON),
        fix=raw["fix"],
        message=raw.get("message", ""),
        source=source,
    )


def _load_curated(path: Path) -> tuple[list[ApiEntry], list[ApiEntry], dict]:
    with path.open("rb") as fh:
        data = tomllib.load(fh)
    apis = [_entry(raw, "curated") for raw in data.get("api", [])]
    # Families: one fix template for many names (collections ABCs, numpy aliases).
    for family in data.get("family", []):
        for name, replacement in family["names"].items():
            apis.append(
                _entry(
                    {
                        **{k: v for k, v in family.items() if k not in ("names", "prefix")},
                        "name": f"{family['prefix']}.{name}",
                        "fix": family["fix"].format(name=name, replacement=replacement),
                    },
                    "curated",
                )
            )
    methods = [_entry(raw, "curated") for raw in data.get("method", [])]
    return apis, methods, {"curated": {"path": str(path), "entries": len(apis) + len(methods)}}


def _load_generated(path: Path) -> tuple[list[ApiEntry], dict]:
    if not path.exists():
        return [], {}
    data = json.loads(path.read_text(encoding="utf-8"))
    return [_entry(raw, "typeshed") for raw in data.get("api", [])], {
        "typeshed": data.get("source", {})
    }


@lru_cache(maxsize=1)
def load() -> Knowledge:
    curated_apis, methods, sources = _load_curated(CURATED_PATH)
    generated, gen_sources = _load_generated(TYPESHED_PATH)
    sources.update(gen_sources)
    apis: dict[str, ApiEntry] = {e.name: e for e in generated}
    apis.update({e.name: e for e in curated_apis})  # curated wins
    return Knowledge(apis, {m.name: m for m in methods}, sources)


__all__ = ["ApiEntry", "Knowledge", "load", "parse_version"]
